styles:
:root{
  --ink:#1b2430; --ink-soft:#4a5568; --paper:#f6f4ef; --panel:#ffffff;
  --gold:#b8925a; --gold-deep:#8f6f42; --line:#e4ddd0;
  --available:#3f8f6b; --sold:#b5484c; --construction:#c98a2c; --upcoming:#3b6ea5;
  --shadow:0 10px 30px rgba(27,36,48,0.14);
}
*{box-sizing:border-box;}
body,html{margin:0;padding:0;height:100%;width:100%;font-family:'Inter',sans-serif;background:var(--paper);color:var(--ink);}
/* Blocks casual text-selection/copying of page content. Inputs stay
   selectable so visitors can still type and edit form fields normally. */
body{ -webkit-user-select:none; user-select:none; }
input, textarea{ -webkit-user-select:text; user-select:text; }
img{ -webkit-user-drag:none; user-drag:none; pointer-events:auto; }
#map{position:absolute;inset:0;z-index:0;}
#map.night-mode .leaflet-tile-pane{
  filter: invert(100%) hue-rotate(180deg) brightness(96%) contrast(88%);
}

#topbar{
  position:fixed;top:0;left:0;right:0;z-index:1200;
  display:flex;align-items:center;justify-content:space-between;
  padding:12px 26px;
  background:transparent;
}
#topbar .brand{
  display:flex;flex-direction:column;align-items:center;gap:4px;color:var(--ink);
  background:rgba(255,255,255,0.8);backdrop-filter:blur(6px);
  padding:10px 18px;border-radius:12px;
  box-shadow:0 2px 10px rgba(27,36,48,0.12);
  transition:padding .25s ease, width .25s ease, height .25s ease, border-radius .25s ease;
  cursor:pointer;
}
/* Auto-collapses to just the icon after 30s (see collapseBrand() in the
   main script) — shrinks to a small round badge instead of the full
   logo+title panel. Hovering (desktop) or tapping (touch) it brings the
   full panel back. */
#topbar .brand.collapsed{
  width:44px;height:44px;padding:8px;border-radius:50%;
  justify-content:center;
}
#topbar .brand.collapsed .brand-text{display:none;}
#topbar .brand.collapsed .brand-logos{gap:0;}
#topbar .brand.collapsed .brand-by,
#topbar .brand.collapsed .logo-secondary{display:none;}
#topbar .brand.collapsed img.logo{height:26px;max-width:26px;}
.brand-logos{display:flex;align-items:center;gap:8px;}
/* Brand stack: logo panel on top, intro video panel directly below it
   (not beside it) — video panel hidden until the "Intro video" script
   shows it. */
#brand-stack{display:flex;flex-direction:column;align-items:center;gap:8px;}
#intro-video-panel{
  display:none;
  background:rgba(255,255,255,0.8);backdrop-filter:blur(6px);
  border-radius:12px;box-shadow:0 2px 10px rgba(27,36,48,0.12);
  padding:6px;
}
#intro-video-panel.show{display:block;}
#brand-video-wrap{
  width:220px;height:124px;border-radius:8px;overflow:hidden;
  background:#000;flex:none;position:relative;
}
#brand-video-frame{position:absolute;inset:0;width:100%;height:100%;}
#brand-video-frame iframe{position:absolute;inset:0;width:100%;height:100%;border:0;display:block;}
@media (max-width:640px){
  #brand-video-wrap{width:150px;height:84px;}
}
.brand-by{font-size:11px;font-style:italic;color:var(--ink-soft);flex:none;}
#topbar .brand img.logo{height:38px;width:auto;max-width:130px;object-fit:contain;display:block;transition:height .25s ease,max-width .25s ease;}
#topbar .brand img.logo-secondary{height:28px;max-width:90px;}
#topbar .brand .brand-text{display:flex;flex-direction:column;align-items:center;text-align:center;}
#topbar .brand h1{font-family:'Playfair Display',serif;font-size:19px;margin:0;letter-spacing:.3px;color:var(--ink);}
#topbar .brand span{font-size:10.5px;color:var(--ink-soft);letter-spacing:1px;text-transform:uppercase;margin-top:1px;}
#toolbar{display:flex;gap:8px;align-items:center;position:relative;}
#search-input{
  width:220px;padding:10px 16px;border-radius:999px;
  border:1px solid #e6dfd0;background:#ffffff;
  font-size:13px;color:var(--ink);font-family:'Inter',sans-serif;
  box-shadow:0 1px 4px rgba(27,36,48,0.1);
  text-overflow:ellipsis;
}
#search-input::placeholder{color:#8a8577;}
#search-input:focus{outline:2px solid var(--gold);}
.btn{
  border:1px solid #e6dfd0;background:#ffffff;color:#1b2430;
  padding:10px 16px;border-radius:999px;font-size:13px;font-weight:600;cursor:pointer;
  display:flex;align-items:center;gap:6px;transition:.2s ease;white-space:nowrap;
  text-decoration:none;
  box-shadow:0 1px 4px rgba(27,36,48,0.1);
}
.btn:hover{background:var(--gold);color:#241a0d;border-color:var(--gold);transform:translateY(-1px);box-shadow:0 5px 12px rgba(184,146,90,0.4);}
.btn.on{background:var(--ink);color:#fff;border-color:var(--ink);}
.btn.on:hover{background:#000;color:#fff;border-color:#000;}
.btn:focus-visible{outline:3px solid var(--gold);outline-offset:2px;}

#area-toast{
  position:fixed;top:86px;left:50%;transform:translateX(-50%) translateY(-8px);
  z-index:1300;background:var(--ink);color:#fff;padding:9px 20px;border-radius:999px;
  font-size:13px;font-weight:600;letter-spacing:.2px;box-shadow:0 8px 24px rgba(27,36,48,0.3);
  opacity:0;pointer-events:none;transition:opacity .25s ease, transform .25s ease;
  white-space:nowrap;
}
#area-toast.show{opacity:1;transform:translateX(-50%) translateY(0);}

/* TV / kiosk mode: append ?tv=1 to the URL. Makes the recenter button
   large and impossible to miss on a big screen with a remote/D-pad. */
body.tv-mode #btn-near-me{
  padding:16px 26px;font-size:16px;border-width:2px;border-color:var(--gold);
  box-shadow:0 6px 20px rgba(184,146,90,0.45);
}
body.tv-mode #topbar{padding:20px 30px;}
body.tv-mode #search-input{font-size:15px;padding:12px 18px;}

#legend{
  position:absolute;bottom:20px;left:20px;z-index:1200;background:var(--panel);
  border-radius:10px;box-shadow:var(--shadow);padding:12px 16px;font-size:12px;max-width:210px;
}
#legend h4{margin:0 0 8px;font-family:'Playfair Display',serif;font-size:13px;color:var(--ink);display:flex;align-items:center;justify-content:space-between;cursor:pointer;user-select:none;}
#legend.collapsed h4{margin-bottom:0;}
#legend.collapsed #legend-content{display:none;}
#legend-arrow{font-size:10px;color:var(--ink-soft);transition:transform .2s ease;}
#legend.collapsed #legend-arrow{transform:rotate(-90deg);}
#legend .row{display:flex;align-items:center;gap:8px;margin-bottom:5px;color:var(--ink-soft);}
#legend .swatch{width:11px;height:11px;border-radius:50%;flex:none;}

/* Sticky WhatsApp / Call buttons — fixed to the viewport, always
   reachable while browsing the map. Sits above Leaflet's bottom-right
   zoom control so the two never overlap. */
#sticky-contact{
  position:fixed;right:20px;bottom:104px;z-index:1250;
  display:flex;flex-direction:column;gap:12px;
}
#sticky-contact a{
  width:52px;height:52px;border-radius:50%;flex:none;
  display:flex;align-items:center;justify-content:center;
  box-shadow:0 6px 18px rgba(27,36,48,0.3);color:#fff;
  transition:transform .2s ease, box-shadow .2s ease;
}
#sticky-contact a:hover{transform:translateY(-2px) scale(1.06);box-shadow:0 10px 24px rgba(27,36,48,0.38);}
#sticky-contact a:focus-visible{outline:3px solid var(--gold);outline-offset:3px;}
#sticky-whatsapp{background:#25D366;}
#sticky-call{background:var(--ink);}
#sticky-contact svg{width:26px;height:26px;}
@media (max-width:640px){
  #sticky-contact{right:14px;bottom:88px;gap:10px;}
  #sticky-contact a{width:46px;height:46px;}
  #sticky-contact svg{width:22px;height:22px;}
}
@media (max-width:380px){
  #sticky-contact{right:10px;bottom:80px;gap:8px;}
  #sticky-contact a{width:42px;height:42px;}
  #sticky-contact svg{width:20px;height:20px;}
}
body.tv-mode #sticky-contact{display:none;} /* remote/D-pad has no use for a tap-to-call button */

.pin-wrap{width:32px;height:44px;position:relative;transform-origin:50% 100%;}
.pin-circle{
  position:absolute;top:0;left:2px;width:28px;height:28px;border-radius:50%;
  box-shadow:0 3px 7px rgba(0,0,0,0.35);
  display:flex;align-items:center;justify-content:center;overflow:hidden;
  border:2px solid rgba(255,255,255,0.9);
}
.pin-circle img{width:100%;height:100%;object-fit:cover;}
.pin-circle .glyph{color:#fff;font-size:13px;}
.pin-tail{
  position:absolute;top:22px;left:50%;transform:translateX(-50%);
  width:0;height:0;border-left:7px solid transparent;border-right:7px solid transparent;
  border-top:15px solid currentColor;filter:drop-shadow(0 2px 1px rgba(0,0,0,0.25));
}
.pin-ground{
  position:absolute;bottom:1px;left:50%;transform:translateX(-50%);
  width:10px;height:4px;border-radius:50%;background:rgba(0,0,0,0.28);filter:blur(1px);
}
.pin-radar{
  position:absolute;top:0;left:2px;width:28px;height:28px;border-radius:50%;
  border:3px solid currentColor;animation:radar-pulse 1.6s ease-out infinite;pointer-events:none;
}
@keyframes radar-pulse{
  0%{transform:scale(0.6);opacity:0.9;}
  100%{transform:scale(2.6);opacity:0;}
}
.infra-pin{
  border-radius:10px;border:2.5px solid rgba(255,255,255,0.95);
  display:flex;align-items:center;justify-content:center;
  box-shadow:0 6px 14px rgba(0,0,0,0.45), inset 0 2px 3px rgba(255,255,255,0.5), inset 0 -3px 5px rgba(0,0,0,0.25);
  background-image:linear-gradient(145deg, rgba(255,255,255,0.35), rgba(0,0,0,0.15));
  background-blend-mode:overlay;
  transition:transform .15s ease, box-shadow .15s ease;
  cursor:pointer;
}
.infra-pin:hover{
  transform:scale(1.15) translateY(-2px);
  box-shadow:0 10px 20px rgba(0,0,0,0.5), inset 0 2px 3px rgba(255,255,255,0.6), inset 0 -3px 5px rgba(0,0,0,0.3);
}
.infra-pin img{width:70%;height:70%;object-fit:contain;filter:drop-shadow(0 1px 1px rgba(0,0,0,0.4));}

.teaser-popup .leaflet-popup-content-wrapper,
.infra-hover-popup .leaflet-popup-content-wrapper,
.road-hover-popup .leaflet-popup-content-wrapper {
  border-radius:12px;padding:0;box-shadow:0 12px 30px rgba(27,36,48,0.3);border:none;
}
.teaser-popup .leaflet-popup-content,
.infra-hover-popup .leaflet-popup-content,
.road-hover-popup .leaflet-popup-content {
  margin:0;
  /* Mobile/tablet: fluid width tied to the viewport. */
  width:clamp(300px, 88vw, 360px) !important;
  max-width:calc(100vw - 16px) !important;
}
/* Desktop: was pinned to a single fixed 360px regardless of window size —
   now it actually scales with the browser window instead of staying the
   same size on a small laptop and a huge monitor. */
@media (min-width:641px){
  .teaser-popup .leaflet-popup-content,
  .infra-hover-popup .leaflet-popup-content,
  .road-hover-popup .leaflet-popup-content {
    width:clamp(320px, 24vw, 400px) !important;
  }
}
/* Tall cards (logo + video + every field) get their own scroll instead
   of overflowing past the bottom of a short mobile screen. */
.teaser-popup .leaflet-popup-content{
  max-height:calc(100vh - 110px);
  overflow-y:auto;
  -webkit-overflow-scrolling:touch;
}
@media (max-width:640px){
  .teaser-popup .leaflet-popup-content{ max-height:calc(100dvh - 100px); }
}
.teaser-popup .leaflet-popup-tip,
.infra-hover-popup .leaflet-popup-tip,
.road-hover-popup .leaflet-popup-tip {display:none;}

.teaser-card{font-family:'Inter',sans-serif;border-radius:12px;overflow:hidden;background:#fff;}
.teaser-card img{width:100%;height:120px;object-fit:cover;display:block;}
/* Logo banner: centred logo in its own framed box at the top */
.tc-logo-wrap{
  display:flex;align-items:center;justify-content:center;
  background:#fff;padding:16px;border-bottom:1px solid var(--line);
  min-height:80px;
}
.tc-logo-wrap img{
  width:auto;height:auto;max-height:72px;max-width:80%;
  object-fit:contain;display:block;
}
.teaser-card .tc-body{padding:14px 16px 14px;}
/* Header row: logo left, name + key details right — 50/50 split */
.tc-top{
  display:grid;grid-template-columns:1fr 1fr;align-items:stretch;
  border-bottom:1px solid var(--line);
}
.tc-top.no-logo{grid-template-columns:1fr;}
.tc-top .tc-logo-wrap{
  border-bottom:none;border-right:1px solid var(--line);
  padding:12px;min-height:0;
}
.tc-top .tc-logo-wrap img{max-width:100%;max-height:96px;height:auto;}
.tc-head{padding:14px 14px 12px;min-width:0;}
.tc-head .tc-title{margin-bottom:6px;overflow-wrap:anywhere;}
.tc-head .tc-field{margin-bottom:5px;}
.tc-head .tc-meta{font-size:12.5px;overflow-wrap:anywhere;}
.tc-head .tc-status,.tc-head .tc-type{font-size:10.5px;padding:3px 9px;}
.tc-body > .tc-brochure-label:first-child{margin-top:-14px;border-top:none;}
.teaser-card .tc-title{
  font-family:'Playfair Display',serif;font-size:15px;font-weight:700;
  color:var(--ink);margin:0 0 8px;line-height:1.35;
}
.teaser-card .tc-details{margin-bottom:4px;}
.teaser-card .tc-field{margin-bottom:6px;line-height:1.4;}
.teaser-card .tc-field:last-child{margin-bottom:0;}
.teaser-card .tc-meta{font-size:13px;color:var(--ink-soft);line-height:1.4;}
.teaser-card .tc-status{
  display:inline-block;padding:3px 10px;border-radius:20px;
  font-size:11px;font-weight:700;color:#fff;margin-right:5px;
}
.teaser-card .tc-type{
  display:inline-block;padding:3px 10px;border-radius:20px;
  font-size:11px;font-weight:600;color:var(--ink-soft);background:#f0ebe0;
}
/* PROJECT VIDEO section — full-bleed out of body padding */
.tc-brochure-label{
  background:var(--paper);color:var(--ink-soft);font-size:10px;font-weight:700;
  text-transform:uppercase;letter-spacing:.8px;
  padding:8px 16px;margin:12px -16px 0;
  border-top:1px solid var(--line);border-bottom:1px solid var(--line);
}
.tc-brochure-media{
  display:block;
  width:calc(100% + 32px);
  margin:0 -16px;
  /* 16:9 of the card body width (card - 32px padding) */
  aspect-ratio:16/9;
  height:auto;
  min-height:160px;
  background:#000;
  position:relative;
  overflow:hidden;
  flex-shrink:0;
}
.tc-brochure-media img.tc-brochure-image{
  width:100%;height:100%;object-fit:cover;display:block;
  position:absolute;inset:0;
}
.tc-video-wrap{
  display:none;
  position:absolute;inset:0;
  width:100%;height:100%;
}
.tc-video-wrap.playing{display:block;}
.tc-video-wrap iframe{
  display:block;
  position:absolute;inset:0;
  width:100%;height:100%;
  border:0;
}
.tc-video-fallback{
  position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  color:#fff;background:rgba(0,0,0,0.35);font-family:'Inter',sans-serif;
  font-size:14px;font-weight:700;text-decoration:none;letter-spacing:.3px;
  transition:background .15s ease;
}
.tc-video-fallback:hover{background:rgba(0,0,0,0.5);}
/* Action buttons */
.teaser-card .tc-actions{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap;}
.teaser-card .tc-whatsapp{
  display:flex;align-items:center;justify-content:center;gap:5px;flex:1;
  background:#25D366;color:#fff;border:none;border-radius:8px;
  padding:10px 0;font-size:13px;font-weight:700;text-decoration:none;
  font-family:'Inter',sans-serif;transition:.15s ease;
}
.teaser-card .tc-whatsapp:hover{background:#1ebe57;}
.teaser-card .tc-whatsapp svg{width:16px;height:16px;flex:none;display:block;}
@media (max-width:640px){ .teaser-card .tc-whatsapp svg{width:19px;height:19px;} }
.teaser-card button{
  flex:1;background:var(--ink);color:#fff;border:none;border-radius:8px;
  padding:10px 0;font-size:13px;font-weight:700;cursor:pointer;
  font-family:'Inter',sans-serif;transition:.15s ease;
}
.teaser-card button:hover{background:#000;}
/* Compact Enquire button (desktop + mobile) */
.teaser-card .tc-actions button[data-pin]{
  flex:0 0 auto;width:auto;padding:0 16px;height:34px;min-height:34px;
  font-size:12.5px;border-radius:999px;
}
.teaser-card button.tc-share{
  flex:1 1 100%;justify-content:center;margin-top:2px;
  background:#fff;color:var(--ink);border:1px solid #e6dfd0;padding:9px 12px;
  display:flex;align-items:center;gap:5px;border-radius:8px;
}
.teaser-card button.tc-share:hover{background:var(--gold);color:#241a0d;border-color:var(--gold);}
@media (max-width:480px){
  .tc-brochure-media{min-height:140px;}
}
/* Mobile: the action buttons stay pinned to the bottom of the card while
   it scrolls, and Share sits on the same row as a compact icon button —
   before, it was on its own row below the fold and never seen. */
@media (max-width:640px){
  .teaser-card{overflow:clip;}
  .teaser-card .tc-actions{
    position:sticky;bottom:0;z-index:2;flex-wrap:nowrap;
    background:#fff;margin:12px -16px -14px;padding:10px 16px 12px;
    border-top:1px solid var(--line);
    box-shadow:0 -6px 14px rgba(27,36,48,0.06);
  }
  .teaser-card button.tc-share{
    flex:0 0 46px;width:46px;margin-top:0;padding:0;font-size:17px;
  }
  .teaser-card .tc-share-label{display:none;}
}

.infra-hover-card, .road-hover-card { font-family: 'Inter', sans-serif; overflow: hidden; }
.infra-hover-card .ihc-header, .road-hover-card .rhc-header { display: flex; align-items: center; gap: 10px; padding: 12px 14px; color: #fff; }
.infra-hover-card .ihc-emoji, .road-hover-card .rhc-emoji { font-size: 24px; line-height: 1; }
.infra-hover-card .ihc-emoji img { width: 28px; height: 28px; object-fit: contain; }
.infra-hover-card .ihc-title-wrap, .road-hover-card .rhc-title-wrap { flex: 1; min-width: 0; }
.infra-hover-card .ihc-title, .road-hover-card .rhc-title { font-family: 'Playfair Display', serif; font-size: 14px; font-weight: 600; color: #fff; margin: 0; line-height: 1.3; word-wrap: break-word; }
.infra-hover-card .ihc-type, .road-hover-card .rhc-type { font-size: 10px; font-weight: 600; color: rgba(255,255,255,0.85); text-transform: uppercase; letter-spacing: 0.5px; margin-top: 2px; }
.infra-hover-card .ihc-body, .road-hover-card .rhc-body { padding: 12px 14px; background: var(--panel); }
.infra-hover-card .ihc-notes, .road-hover-card .rhc-notes { font-size: 12px; color: var(--ink-soft); line-height: 1.4; margin: 0; word-wrap: break-word; }
.infra-hover-card .ihc-empty, .road-hover-card .rhc-empty { font-size: 11px; color: var(--ink-soft); font-style: italic; margin: 0; }
.road-hover-card .rhc-footer { padding: 8px 14px; background: var(--paper); border-top: 1px solid var(--line); font-size: 10px; color: var(--ink-soft); display: flex; align-items: center; gap: 4px; }

.leaflet-popup-content{font-family:'Inter',sans-serif;font-size:12.5px;}
.leaflet-control-attribution{ max-width:58vw; font-size:10px; line-height:1.5; }
.leaflet-popup-content b{font-family:'Playfair Display',serif;}

/* Overlay shared by lead modal + detail panel */
#overlay-bg{
  position:absolute;inset:0;z-index:1700;background:rgba(27,36,48,0.5);
  display:none;align-items:center;justify-content:center;
}
#overlay-bg.open{display:flex;}

#lead-box{
  width:360px;max-width:92vw;background:var(--panel);border-radius:14px;box-shadow:var(--shadow);
  padding:24px 24px 20px;
}
#lead-box h3{margin:0 0 4px;font-family:'Playfair Display',serif;font-size:clamp(17px,4.5vw,19px);color:var(--ink);}
#lead-box p{margin:0 0 16px;font-size:12.5px;color:var(--ink-soft);}
.field{margin-bottom:13px;}
.field label{display:block;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--ink-soft);margin-bottom:5px;}
.field input, .field select{
  width:100%;padding:10px 11px;border:1px solid var(--line);border-radius:7px;font-size:13.5px;
  font-family:'Inter',sans-serif;color:var(--ink);background:#fdfcfa;
}
.field input:focus, .field select:focus{outline:2px solid var(--gold);border-color:var(--gold);}
#lead-error{font-size:11.5px;color:var(--sold);min-height:14px;margin-bottom:6px;}
#lead-consent-row{display:flex;align-items:flex-start;gap:9px;margin-bottom:14px;}
#lead-consent-row input[type=checkbox]{width:17px;height:17px;flex:none;margin-top:2px;cursor:pointer;}
#lead-consent-row label{font-size:10.5px;line-height:1.5;color:var(--ink-soft);font-weight:400;text-transform:none;letter-spacing:0;cursor:pointer;}
.lead-actions{display:flex;gap:10px;margin-top:6px;}
.lead-actions button{flex:1;padding:11px 0;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;border:1px solid var(--line);}
#lead-submit{background:var(--gold);color:#241a0d;border-color:var(--gold);touch-action:manipulation;}
#lead-submit:hover{background:var(--gold-deep);color:#fff;}
#lead-cancel{background:#fff;color:var(--ink-soft);}

#detail-panel{
  position:absolute;top:0;right:0;height:100%;width:400px;max-width:92vw;
  background:var(--panel);box-shadow:-8px 0 30px rgba(27,36,48,0.2);
  z-index:1500;transform:translateX(100%);transition:transform .28s ease;
  display:flex;flex-direction:column;
}
#detail-panel.open{transform:translateX(0);}
#detail-head{padding:0;position:relative;}
#detail-head img{width:100%;height:200px;object-fit:cover;display:block;}
#detail-close{
  position:absolute;top:14px;right:14px;background:rgba(27,36,48,0.6);color:#fff;border:none;
  width:32px;height:32px;border-radius:50%;font-size:15px;cursor:pointer;
  display:flex;align-items:center;justify-content:center;padding:0;line-height:1;
}
#detail-body{padding:22px 24px;overflow-y:auto;flex:1;}
#detail-body h2{font-family:'Playfair Display',serif;font-size:clamp(18px,5vw,22px);margin:0 0 6px;}
#detail-body .status-badge{display:inline-block;padding:3px 10px;border-radius:12px;font-size:11px;font-weight:700;color:#fff;margin-bottom:14px;}
.detail-row{margin-bottom:16px;}
.detail-row label{display:block;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--ink-soft);margin-bottom:4px;}
.detail-row .value{font-size:14.5px;color:var(--ink);line-height:1.5;}
.detail-row .value.price{font-family:'Playfair Display',serif;font-size:19px;color:var(--gold-deep);}
.detail-share{
  width:100%;margin-top:6px;background:#fff;color:var(--ink);border:1px solid #e6dfd0;
  border-radius:8px;padding:11px 0;font-size:13px;font-weight:700;cursor:pointer;
  font-family:'Inter',sans-serif;display:flex;align-items:center;justify-content:center;gap:7px;
}
.detail-share:hover{background:var(--gold);color:#241a0d;border-color:var(--gold);}

/* Legal (Privacy / Disclaimer) popup */
#legal-overlay{
  position:fixed;inset:0;z-index:1900;background:rgba(27,36,48,0.55);
  display:none;align-items:center;justify-content:center;padding:20px;
}
#legal-overlay.open{display:flex;}
#legal-box{
  width:640px;max-width:100%;max-height:85vh;background:var(--panel);
  border-radius:14px;box-shadow:var(--shadow);display:flex;flex-direction:column;overflow:hidden;
}
#legal-box-head{
  display:flex;align-items:center;justify-content:space-between;
  padding:20px 24px;border-bottom:1px solid var(--line);flex:none;
}
#legal-box-head h2{font-family:'Playfair Display',serif;font-size:clamp(16px,4.5vw,20px);margin:0;color:var(--ink);line-height:1.3;}
#legal-close{
  background:var(--paper);border:1px solid var(--line);color:var(--ink-soft);
  width:32px;height:32px;border-radius:50%;font-size:14px;cursor:pointer;flex:none;
  display:flex;align-items:center;justify-content:center;padding:0;line-height:1;
  transition:.2s ease;
}
#legal-close:hover{background:var(--gold);color:#241a0d;border-color:var(--gold);}
#legal-body{
  padding:26px 28px;overflow-y:auto;line-height:1.75;font-size:14.5px;color:var(--ink-soft);
}
#legal-body h3{font-family:'Playfair Display',serif;font-size:17px;color:var(--ink);margin:24px 0 10px;line-height:1.3;}
#legal-body h3:first-child{margin-top:0;}
#legal-body p{margin:0 0 14px;}
#legal-body ul{margin:0 0 14px;padding-left:22px;}
#legal-body li{margin-bottom:6px;}
#legal-body .contact-block{
  background:var(--paper);border:1px solid var(--line);border-radius:10px;
  padding:16px 18px;margin:8px 0 16px;font-size:13.5px;color:var(--ink);line-height:1.6;
}
#legal-body .contact-block strong{display:block;font-family:'Playfair Display',serif;font-size:15px;margin-bottom:6px;}
#legal-body .legal-updated{font-size:11.5px;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.5px;margin:0 0 18px;}
#legal-body a{color:var(--gold-deep);}

#loading{
  position:absolute;inset:0;z-index:2000;background:var(--paper);
  display:flex;align-items:center;justify-content:center;flex-direction:column;gap:10px;
  font-family:'Playfair Display',serif;color:var(--ink-soft);
}
#loading .spin{width:26px;height:26px;border:3px solid var(--line);border-top-color:var(--gold);border-radius:50%;animation:spin 0.9s linear infinite;}
@keyframes spin{to{transform:rotate(360deg);}}

#search-suggestions{
  display:none;position:absolute;top:calc(100% + 6px);left:0;right:0;
  background:var(--panel);border-radius:12px;box-shadow:var(--shadow);
  padding:6px;max-height:320px;overflow-y:auto;z-index:1300;
}
#search-suggestions.open{display:block;}
.suggestion-item{
  padding:9px 12px;border-radius:8px;font-size:13px;color:var(--ink);
  cursor:pointer;font-family:'Inter',sans-serif;transition:.15s ease;
  display:flex;align-items:center;justify-content:space-between;gap:10px;
}
.suggestion-item:hover, .suggestion-item.active{background:var(--paper);color:var(--gold-deep);}
.suggestion-item .sg-type{font-size:10px;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.4px;flex:none;}

#btn-near-me.locating{opacity:.7;pointer-events:none;}
.me-pulse{
  width:16px;height:16px;border-radius:50%;background:#2c78e0;
  border:3px solid #fff;box-shadow:0 0 0 rgba(44,120,224,0.5);
  animation:me-ping 1.8s infinite;
}
@keyframes me-ping{
  0%{box-shadow:0 0 0 0 rgba(44,120,224,0.5);}
  70%{box-shadow:0 0 0 14px rgba(44,120,224,0);}
  100%{box-shadow:0 0 0 0 rgba(44,120,224,0);}
}

@media (max-width:640px){
  #topbar{ flex-wrap:wrap; gap:8px; padding:10px 12px; }
  #topbar .brand .brand-text{ display:none; }
  #topbar .brand{ padding:6px 10px; }
  #topbar .brand-logos{ gap:6px; }
  #topbar .brand img.logo-main{ height:32px; }
  #topbar .brand img.logo-secondary{ height:24px; max-width:70px; }
  #topbar .brand-by{ font-size:10px; }
  #toolbar{ width:100%; flex-wrap:nowrap; }
  #search-input{ flex:1 1 auto; width:auto; min-width:0; min-height:38px; padding:8px 12px; font-size:12px; order:1; }
  .btn{
    padding:0; width:38px; height:38px; min-height:38px; flex:0 0 38px;
    font-size:15px; justify-content:center; white-space:nowrap; order:2;
    border-radius:50%;
  }
  /* Text label hidden on the compact mobile row — icon only, with the
     full label still read by screen readers via aria-label. */
  .btn .btn-label{ display:none; }
  #legend{
    left:12px; right:12px; bottom:12px; max-width:none;
    max-height:45vh; overflow-y:auto; font-size:12px; padding:12px 14px;
  }
  #legend .row{ margin-bottom:6px; min-height:28px; }
  #legend-toggle{ padding:6px 2px; min-height:36px; display:flex; align-items:center; justify-content:space-between; }
  #lead-box{ padding:18px 18px 16px; }
  .lead-actions button{ min-height:46px; }
  #detail-panel{width:100%;}
  #detail-body{ padding:18px 16px; }
  #detail-close{ width:40px; height:40px; }
  #legal-box{ max-height:90vh; }
  #legal-box-head{ padding:16px 18px; }
  #legal-body{ padding:18px 18px; font-size:13.5px; }
  .teaser-card .tc-whatsapp, .teaser-card button{ min-height:42px; font-size:13.5px; }
  .leaflet-popup-close-button{ width:34px !important; height:34px !important; font-size:22px !important; }
  .leaflet-control-attribution{ max-width:85vw; font-size:9px; line-height:1.4; }
  /* Removes the ~300ms tap delay and stray double-tap zoom on buttons/cards
     so taps register immediately, the way a native app feels. */
  .btn, .teaser-card button, .teaser-card .tc-whatsapp, #legend-toggle,
  #detail-close, .lead-actions button, .leaflet-marker-icon{
    touch-action:manipulation; -webkit-tap-highlight-color:transparent;
  }
}
@media (max-width:380px){
  #topbar .brand span{ display:none; }
  #topbar .brand-by, #topbar .brand img.logo-secondary{ display:none; }
  #search-input{ font-size:12px; }
  .leaflet-control-attribution{ max-width:92vw; font-size:8.5px; }
}
@media (hover:none) and (pointer:coarse){
  /* Touch devices can't hover, so give buttons a visible pressed state
     instead — otherwise taps feel unresponsive with no feedback at all. */
  .btn:active, .teaser-card button:active, .teaser-card .tc-whatsapp:active{
    transform:scale(0.96); opacity:.9;
  }
}

/* ---------- Mobile: single-line header + compact legend ---------- */
@media (max-width:640px){
  /* Logo badge, search and satellite all sit on one row */
  #topbar{ flex-wrap:nowrap; align-items:center; gap:8px; padding:10px 10px; }
  #brand-stack{ position:relative; flex:none; }
  #topbar .brand,
  #topbar .brand.collapsed{
    width:44px; height:44px; padding:6px; border-radius:50%;
    justify-content:center; flex:none;
    background:#fff; box-shadow:0 2px 10px rgba(27,36,48,0.14);
  }
  #topbar .brand .brand-text,
  #topbar .brand .brand-by,
  #topbar .brand .logo-secondary{ display:none; }
  #topbar .brand .brand-logos{ gap:0; }
  #topbar .brand img.logo,
  #topbar .brand img.logo-main{ width:32px; height:32px; max-width:32px; object-fit:contain; }
  /* Intro video floats under the badge instead of widening the row */
  #intro-video-panel{ position:absolute; top:calc(100% + 8px); left:0; }
  #toolbar{ flex:1 1 auto; width:auto; min-width:0; gap:6px; }
  #search-input{ height:44px; min-height:44px; font-size:14px; padding:8px 16px; }
  .btn{ width:44px; height:44px; min-height:44px; flex:0 0 44px; }

  /* Near Me removed on mobile (location is still detected on page load) */
  #btn-near-me{ display:none !important; }

  /* Legend: small pill at bottom-left, opens upward when tapped */
  #legend{
    left:10px; right:auto; bottom:14px;
    max-width:min(240px, calc(100vw - 90px));
    padding:6px 12px; border-radius:999px; font-size:11.5px;
  }
  #legend:not(.collapsed){ border-radius:12px; padding:10px 12px; max-height:45vh; }
  #legend-toggle{ min-height:26px; padding:0; font-size:12px; gap:8px; }
  #legend .row{ min-height:22px; margin-bottom:4px; }
}

/* ---------- Project card: close button + mobile polish ---------- */
.teaser-popup .tc-close{
  position:absolute;top:8px;right:8px;z-index:20;
  width:34px;height:34px;border-radius:50%;border:none;padding:0;
  display:flex;align-items:center;justify-content:center;
  background:rgba(255,255,255,0.95);color:var(--ink);
  font-size:22px;line-height:1;cursor:pointer;
  box-shadow:0 2px 8px rgba(27,36,48,0.18);
  touch-action:manipulation;-webkit-tap-highlight-color:transparent;
}
.teaser-popup .tc-close:hover{background:var(--gold);color:#241a0d;}
.tc-head{padding-right:44px;}
@media (max-width:640px){
  /* Card fits between the search bar and the legend, never under them */
  .teaser-popup .leaflet-popup-content{
    width:min(88vw, 350px) !important;
    max-height:calc(100dvh - 190px);
  }
  .teaser-popup .leaflet-popup-content-wrapper{border-radius:14px;}
  .tc-top .tc-logo-wrap{padding:6px;}
  .tc-top .tc-logo-wrap img{width:100%;max-width:100%;max-height:120px;}
  .tc-head{padding:12px 44px 10px 12px;}
  .teaser-card .tc-title{font-size:14.5px;margin-bottom:4px;}
  .tc-head .tc-meta{font-size:12px;}
  .tc-head .tc-field{margin-bottom:4px;}
  .teaser-card .tc-body{padding:12px 14px;}
  .teaser-card .tc-meta{font-size:12.5px;}
  .teaser-card .tc-field{margin-bottom:4px;}
  .tc-brochure-label{padding:6px 14px;margin:10px -14px 0;}
  .tc-brochure-media{width:calc(100% + 28px);margin:0 -14px;min-height:0;}
  /* Smaller action buttons */
  .teaser-card .tc-actions{
    gap:6px;margin:10px -14px -12px;padding:8px 14px 10px;
  }
  .teaser-card .tc-actions button,
  .teaser-card .tc-actions .tc-whatsapp{
    min-height:36px !important;height:36px;padding:0 10px;
    font-size:12.5px !important;border-radius:8px;
  }
  .teaser-card button.tc-share{flex:0 0 36px;width:36px;font-size:15px !important;padding:0;}
  /* WhatsApp: small round icon button on mobile */
  .teaser-card .tc-actions .tc-whatsapp{
    flex:0 0 36px;width:36px;padding:0 !important;border-radius:50% !important;gap:0;
  }
  .teaser-card .tc-whatsapp .tc-wa-label{display:none;}
  .teaser-card .tc-actions button[data-pin]{
    flex:0 0 auto !important;width:auto;padding:0 14px !important;
    height:32px;min-height:32px !important;font-size:12px !important;border-radius:999px !important;
  }
  /* Floating WhatsApp / Call buttons step aside while a card is open */
  body.card-open #sticky-contact{opacity:0;pointer-events:none;transform:translateX(12px);}
  #sticky-contact{transition:opacity .2s ease, transform .2s ease;}
}

/* ===== Compact project card (all screen sizes) ===== */
/* Smaller card */
.teaser-popup .leaflet-popup-content{
  width:min(290px, calc(100vw - 32px)) !important;
  max-height:min(480px, calc(100vh - 110px));
}
@media (max-width:640px){
  .teaser-popup .leaflet-popup-content{
    width:min(80vw, 280px) !important;
    max-height:min(440px, calc(100dvh - 190px));
  }
}
.tc-brochure-media{min-height:0;}

/* Header: logo fills its whole box (cover), text column slightly wider */
.tc-top{grid-template-columns:44% 56%;}
.tc-top.no-logo{grid-template-columns:1fr;}
.tc-top .tc-logo-wrap{
  position:relative;padding:0 !important;min-height:120px;overflow:hidden;
  background:#fff;
}
/* Logo fills the whole box but is never cropped — any logo shape
   (wide, tall, square) scales to fit neatly. */
.tc-top .tc-logo-wrap img{
  position:absolute;inset:8px;width:calc(100% - 16px) !important;height:calc(100% - 16px) !important;
  max-width:none !important;max-height:none !important;object-fit:contain;object-position:center;
}
@media (max-width:640px){ .tc-top .tc-logo-wrap{min-height:110px;} }
.tc-head{padding:10px 34px 10px 10px !important;}
.teaser-card .tc-title{font-size:14px;margin-bottom:4px;}
.tc-head .tc-meta{font-size:11.5px;}
.teaser-card .tc-body{padding:10px 12px;}
.teaser-card .tc-meta{font-size:12px;}
.tc-brochure-label{padding:6px 12px;margin:10px -12px 0;}
.tc-brochure-media{width:calc(100% + 24px);margin:0 -12px;}
.teaser-popup .tc-close{width:28px;height:28px;font-size:18px;top:6px;right:6px;}

/* Action row: small Enquire pill + round WhatsApp + round Share */
.teaser-card .tc-actions{
  flex-wrap:nowrap;align-items:center;gap:8px;margin-top:10px;
}
.teaser-card .tc-actions .tc-whatsapp,
.teaser-card .tc-actions button.tc-share{
  flex:0 0 34px !important;width:34px !important;height:34px !important;
  min-height:34px !important;padding:0 !important;margin:0;gap:0;
  border-radius:50% !important;display:flex;align-items:center;justify-content:center;
  font-size:15px !important;
}
.teaser-card .tc-whatsapp .tc-wa-label,
.teaser-card .tc-share-label{display:none !important;}
.teaser-card .tc-whatsapp svg{width:18px !important;height:18px !important;}
@media (max-width:640px){
  .teaser-card .tc-actions{margin:10px -12px -10px;padding:8px 12px 10px;}
}

/* ===== Card: hidden scrollbar + floating action buttons ===== */
/* Card still scrolls, but the scrollbar is hidden */
.teaser-popup .leaflet-popup-content{scrollbar-width:none;-ms-overflow-style:none;}
.teaser-popup .leaflet-popup-content::-webkit-scrollbar{display:none;width:0;height:0;}

/* Enquire / WhatsApp / Share: small round buttons, stacked and fixed to
   the middle of the card's right edge — they stay put while it scrolls */
.teaser-popup .leaflet-popup-content-wrapper{position:relative;}
.teaser-popup .tc-actions.tc-actions-float{
  position:absolute !important;right:8px;top:50%;transform:translateY(-50%);
  display:flex;flex-direction:column;flex-wrap:nowrap;align-items:center;gap:8px;
  margin:0 !important;padding:0 !important;background:none !important;
  border:none !important;box-shadow:none !important;z-index:15;
}
.teaser-popup .tc-actions-float .tc-whatsapp,
.teaser-popup .tc-actions-float button{
  flex:0 0 36px !important;width:36px !important;height:36px !important;
  min-height:36px !important;padding:0 !important;margin:0 !important;gap:0 !important;
  border-radius:50% !important;display:flex !important;align-items:center;justify-content:center;
  font-size:15px !important;box-shadow:0 3px 10px rgba(27,36,48,0.25);
  border:2px solid #fff !important;
}
.teaser-popup .tc-actions-float button[data-pin]{background:var(--ink);color:#fff;}
.teaser-popup .tc-actions-float button.tc-share{background:#fff;color:var(--ink);}
.teaser-popup .tc-actions-float svg{width:18px !important;height:18px !important;display:block;}
.teaser-popup .tc-enq-label,
.teaser-popup .tc-wa-label,
.teaser-popup .tc-share-label{display:none !important;}
/* Keep text clear of the floating buttons */
.teaser-card .tc-details{padding-right:40px;}

/* ===== Shorter video + tap-friendly pins + responsive polish ===== */
/* Video box a little shorter (2:1 instead of 16:9) */
.tc-brochure-media{aspect-ratio:2/1 !important;min-height:0 !important;}
.tc-video-wrap iframe{position:absolute;inset:0;width:100%;height:100%;border:0;display:block;}
.tc-video-fallback{color:#fff !important;text-shadow:0 1px 4px rgba(0,0,0,0.6);}

/* Pins: bigger invisible tap area so every pin is easy to hit on phones */
.leaflet-marker-icon{cursor:pointer;}
.pin-wrap::before{
  content:'';position:absolute;left:-8px;right:-8px;top:-8px;bottom:-4px;
  border-radius:50%;
}
@media (hover:none), (max-width:640px){
  .pin-wrap::before{left:-12px;right:-12px;top:-12px;bottom:-6px;}
  .infra-pin{position:relative;}
  .infra-pin::before{content:'';position:absolute;inset:-10px;}
}
/* The empty space in the top bar no longer blocks taps on pins under it */
#topbar{pointer-events:none;}
#topbar > *, #topbar #toolbar > *, #search-suggestions{pointer-events:auto;}
#toolbar{pointer-events:none;}
#brand-stack{pointer-events:none;}
#brand-stack > *{pointer-events:auto;}
#intro-video-panel:not(.show){pointer-events:none;}

/* Very small phones */
@media (max-width:360px){
  .teaser-popup .leaflet-popup-content{width:calc(100vw - 28px) !important;}
  .tc-top .tc-logo-wrap{min-height:96px;}
  .teaser-card .tc-title{font-size:13.5px;}
}
/* Landscape phones: card fits the short screen */
@media (max-height:500px) and (orientation:landscape){
  .teaser-popup .leaflet-popup-content{max-height:calc(100dvh - 90px) !important;}
  .tc-brochure-media{aspect-ratio:21/9 !important;}
}

/* ===== Mobile: floating WhatsApp / Call buttons no longer overlap the
   zoom buttons or the map credits ===== */
@media (max-width:640px){
  /* Zoom +/- stays; WhatsApp / Call sit just above it (exact spot is
     measured by placeStickyContact() in the script). */
  #sticky-contact{
    right:12px !important;
    bottom:calc(125px + env(safe-area-inset-bottom, 0px)) !important;
    gap:10px !important;
  }
  #sticky-contact a{width:46px !important;height:46px !important;}
  #sticky-contact svg{width:22px !important;height:22px !important;}
  /* Map credits stay small and readable under the buttons */
  .leaflet-bottom.leaflet-right .leaflet-control-attribution{
    margin:0 !important;padding:2px 6px !important;border-radius:6px 0 0 0;
    background:rgba(255,255,255,0.85) !important;
  }
}
@media (max-width:380px){
  #sticky-contact{right:10px !important;gap:8px !important;}
  #sticky-contact a{width:42px !important;height:42px !important;}
  #sticky-contact svg{width:20px !important;height:20px !important;}
}
/* Phones turned sideways: buttons sit side by side to save height */
@media (max-height:500px) and (orientation:landscape){
  #sticky-contact{flex-direction:row !important;}
}

/* ===== One set of action buttons only + never hidden behind × ===== */
.teaser-popup .leaflet-popup-content .tc-actions{display:none !important;}
.teaser-popup .leaflet-popup-content-wrapper{min-height:176px;}
.teaser-popup .tc-actions.tc-actions-float{
  top:max(44px, calc(50% - 62px)) !important;
  transform:none !important;
  display:flex !important;
}

/* ===== Smaller status badge + "Enquire Now" badge button ===== */
.teaser-card .tc-status,
.teaser-card .tc-head .tc-status{
  font-size:9.5px !important;padding:2px 8px !important;line-height:1.45;
  white-space:nowrap;letter-spacing:.1px;
}
.teaser-card .tc-type,
.teaser-card .tc-head .tc-type{
  font-size:9.5px !important;padding:2px 8px !important;line-height:1.45;white-space:nowrap;
}
.teaser-popup .tc-actions-float button[data-pin]{
  flex:0 0 52px !important;width:52px !important;height:52px !important;min-height:52px !important;
  background:transparent !important;border:none !important;overflow:visible;
  box-shadow:0 4px 12px rgba(47,59,147,0.35);
  transition:transform .2s ease;
}
.teaser-popup .tc-actions-float button[data-pin]:hover{transform:scale(1.07);}
.teaser-popup .tc-actions-float button[data-pin] svg.tc-enq-art{
  width:52px !important;height:52px !important;overflow:visible;
}
.teaser-popup .tc-actions.tc-actions-float{top:max(44px, calc(50% - 70px)) !important;}
.teaser-popup .leaflet-popup-content-wrapper{min-height:192px;}
.teaser-card .tc-details{padding-right:52px;}

/* Floating buttons live outside .teaser-card, so give WhatsApp its green here */
.teaser-popup .tc-actions-float a.tc-whatsapp{background:#25D366 !important;color:#fff !important;text-decoration:none;}
.teaser-popup .tc-actions-float a.tc-whatsapp:hover{background:#1ebe57 !important;}

.teaser-card .tc-rera{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;letter-spacing:.3px;overflow-wrap:anywhere;}

