  const PIN_LIGHT_COLS = 'id,number,lat,lng,title,type,status,price,description,created_at,updated_at,configuration,sqft,possession_timeline,launch_date,whats_available,highlighted,size,developer,location,key_usp,field_visibility,custom_fields,youtube_video_url,brochure_width,brochure_height,rera_number';
