        rows.forEach(r=>{
          pinImageCache.set(r.id, { updated_at:r.updated_at, image:r.image, brochure_image:r.brochure_image });
          const pin = pins.find(p => p.id === r.id);
          if(!pin || (!r.image && !r.brochure_image)) return;
          pin.image = r.image; pin.brochure_image = r.brochure_image;
          refreshPinMarker(pin);
        });
      }
    }
    await Promise.all([worker(), worker(), worker()]);
    // Final check: any pin still without its logo gets another try shortly.
    const missing = pins.filter(p => !p.image && !pinImageCache.has(p.id));
    if(missing.length) setTimeout(()=> loadPinImages(missing), 4000);
  }

  const [pinsRes, infraRes, roadsRes, settingsRes, customTypesRes, areaBoundariesRes] = await Promise.all([
    fetchPinsLight().then(data => ({ data })),
    withRetry(()=> sb.from('infra_markers').select('*')),
    withRetry(()=> sb.from('roads').select('*')),
    withRetry(()=> sb.from('map_settings').select('*').eq('id', 1).single()),
    withRetry(()=> sb.from('infra_types').select('*')),
    withRetry(()=> sb.from('area_boundaries').select('*'), 2)
  ]);
  let pins = pinsRes.data || [];
  const bridges = infraRes.data || [];
  const roads = roadsRes.data || [];
  const boundary = (settingsRes.data && settingsRes.data.boundary) || [];
  // Locality boundaries (Kharadi, Viman Nagar, NIBM/Lullanagar, Solapur
  // Highway...) drawn in the admin tool. Falls back to an empty list if the
  // table doesn't exist yet, so search still works via the hardcoded
  // fallback centres further below.
  const areaBoundaries = (!areaBoundariesRes.error && areaBoundariesRes.data) ? areaBoundariesRes.data : [];

  // Merge in any custom infra types (e.g. "Helipad") before anything renders, so
  // markers and roads pick up the right label/emoji/colour on the very first paint.
  if(!customTypesRes.error && customTypesRes.data){
    customTypesRes.data.forEach(ct => registerCustomInfraType(ct));
  }

  if(boundary.length > 1){
    L.polygon(boundary, {color:'#e74c3c', weight:2, dashArray:'5,5', fillColor:'#e74c3c', fillOpacity:0.03, interactive:false}).addTo(map);
  }

  // ---------- TV / big-screen recentring ----------
  // Root cause of the "scattered on load, fixes itself after +/-" issue:
  // Leaflet measures its container size the instant it initialises. On some
  // TV/smart-display browsers the on-screen container finishes resizing a
  // beat *after* that, so tiles get positioned against a stale size until
  // something (like clicking zoom) forces Leaflet to remeasure. We fix that
  // two ways below: automatically (no input needed) and via a manual button.

  // Shows the whole radius map — boundary if we have one, else every pin —
  // centred and fully framed. Kept as the fallback for kiosk/TV screens and
  // for anyone who declines location access on "Near Me".
  function fitFullMap(){
    map.invalidateSize(true);
    let bounds = null;
    if(boundary.length > 1){
      bounds = L.latLngBounds(boundary);
    } else if(pins.length){
      bounds = L.latLngBounds(pins.map(p => [p.lat, p.lng]));
    }
    if(bounds && bounds.isValid()){
      map.fitBounds(bounds, {padding:[60,60]});
    } else {
      map.setView([18.5215, 73.9140], 14.5);
    }
  }

  // Just remeasures the container and redraws tiles in place, without
  // moving/zooming the view the visitor already has. Safe to call silently
  // and repeatedly.
  function silentResync(){ map.invalidateSize(false); }

  // ---------- "Near Me" (the headline feature) ----------
  // Uses the visitor's real GPS location to surface whichever of our pins
  // are actually close to them — a far stronger hook than a generic
  // "browse listings" button. Falls back to the old full-radius recenter
  // (fitFullMap) if location is denied/unavailable, so TV/kiosk screens
  // (which won't have GPS) keep working exactly as before.
  const nearMeBtn = document.getElementById('btn-near-me');
  let meMarker = null;
  const NEAR_ME_RADIUS_KM = 6;

  function haversineKm(lat1, lng1, lat2, lng2){
    const R = 6371, toRad = d => d * Math.PI / 180;
    const dLat = toRad(lat2 - lat1), dLng = toRad(lng2 - lng1);
    const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng/2)**2;
    return R * 2 * Math.asin(Math.sqrt(a));
  }

  function showNearMe(lat, lng){
    if(meMarker) map.removeLayer(meMarker);
    meMarker = L.marker([lat, lng], {
      icon: L.divIcon({ className:'', html:'<div class="me-pulse"></div>', iconSize:[16,16], iconAnchor:[8,8] })
    }).addTo(map);

    pins.forEach(pin=>{
      const marker = pinMarkerMap.get(pin.id);
      if(marker && !map.hasLayer(marker)) marker.addTo(map);
    });

    const nearby = pins
      .map(p => ({ pin:p, dist: haversineKm(lat, lng, p.lat, p.lng) }))
      .filter(x => x.dist <= NEAR_ME_RADIUS_KM)
      .sort((a,b) => a.dist - b.dist);

    if(nearby.length){
      const bounds = L.latLngBounds([[lat,lng], ...nearby.map(x => [x.pin.lat, x.pin.lng])]);
      map.flyToBounds(bounds, { padding:[90,90], maxZoom:16, animate:true, duration:1.1 });
      showAreaToast(`${nearby.length} project${nearby.length > 1 ? 's' : ''} near you`);
      const closest = pinMarkerMap.get(nearby[0].pin.id);
      if(closest) setTimeout(()=>{
        // Mobile: just highlight the pin — the card opens only when tapped.
        if(!window.matchMedia('(max-width:640px), (hover: none)').matches) closest.openPopup();
        pulseMarker(closest);
      }, 900);
    } else {
      map.flyTo([lat, lng], 13, { animate:true, duration:1.1 });
      showAreaToast('No projects near you yet — showing Mundhwa');
      setTimeout(focusMundhwa, 1400);
    }
  }

  // Single shared entry point for "find the visitor's location and show
  // their nearby projects" — used both by the Near Me button (with visible
  // Locating… UI) and automatically on page load (silently, so a first-time
  // visitor doesn't have to find/tap the button themselves).
  function locateAndShowNearby(opts){
    opts = opts || {};
    if(!navigator.geolocation){
      if(opts.onSettled) opts.onSettled();
      fitFullMap();
      return;
    }
    if(opts.onStart) opts.onStart();
    navigator.geolocation.getCurrentPosition(
      (pos)=>{
        if(opts.onSettled) opts.onSettled();
        showNearMe(pos.coords.latitude, pos.coords.longitude);
      },
      ()=>{
        // Denied, unavailable, or timed out — fall back to the full-radius
        // view. Kept quiet on the automatic page-load attempt (a toast
        // about denied location before the visitor has done anything
        // feels intrusive); the manual button click still explains itself.
        if(opts.onSettled) opts.onSettled();
        if(!opts.silent) showAreaToast('Location unavailable — showing full map');
        fitFullMap();
      },
      { enableHighAccuracy:true, timeout:8000, maximumAge:120000 }
    );
  }

  if(nearMeBtn){
    nearMeBtn.addEventListener('click', ()=>{
      nearMeBtn.classList.add('locating');
      const labelEl = nearMeBtn.querySelector('.btn-label');
      const origLabel = labelEl ? labelEl.textContent : nearMeBtn.textContent;
      if(labelEl) labelEl.textContent = ' Locating…'; else nearMeBtn.textContent = '📍 Locating…';
      locateAndShowNearby({
        onSettled: ()=>{
          nearMeBtn.classList.remove('locating');
          if(labelEl) labelEl.textContent = origLabel; else nearMeBtn.textContent = origLabel;
        }
      });
    });
  }

  // Locality dropdown is populated further below, once knownAreas (from
  // Supabase) is available — see "Locality dropdown" near the area-search code.

  // ?tv=1 in the URL = kiosk/TV mode: bigger, more remote-friendly controls.
  // (The full-radius-map default view below now applies to every visitor,
  // not just TV — ?tv=1 just adjusts sizing for a big screen.)
  const isTvMode = new URLSearchParams(window.location.search).get('tv') === '1';
  if(isTvMode){
    document.body.classList.add('tv-mode');
  }

  // Automatic fix: remeasure a few times as the TV's browser finishes
  // laying out the page and loading fonts/images. This runs regardless of
  // TV mode so it also helps anyone on an unusual screen/resize situation.
  [300, 900, 1800, 3200].forEach(delay => setTimeout(silentResync, delay));
  window.addEventListener('load', silentResync);
  window.addEventListener('resize', silentResync);
  window.addEventListener('orientationchange', silentResync);
  if(document.fonts && document.fonts.ready){
    document.fonts.ready.then(silentResync);
  }

  const pinScale = {small:0.78, medium:1, large:1.35};
  // If a pin/infra image URL is broken or missing on the server, this swaps
  // it out cleanly instead of leaving the browser's ugly broken-image icon
  // showing on the map.
  window.__pinImgFallback = function(imgEl){ imgEl.style.display = 'none'; };
  window.__infraImgFallback = function(imgEl, emoji){ imgEl.outerHTML = emoji; };
  // Markers are ~32px, so they load a small cached thumbnail of the pin's
  // image (served by /api/pins/[id]/image) instead of the full-size file.
  const pinThumb = (src)=> (typeof src === 'string' && src.startsWith('/api/media/')) ? src + '&w=96' : src;
  function pinIcon(pin){
    const color = statusColor[pin.status] || statusColor.available;
    const head = pin.image ? `<img src="${pinThumb(pin.image)}" alt="" onerror="window.__pinImgFallback(this)">` : `<span class="glyph">●</span>`;
    const radar = pin.highlighted ? '<div class="pin-radar"></div>' : '';
    const scale = pinScale[pin.size] || 1;
    return L.divIcon({
      className:'',
      html:`<div class="pin-wrap" style="color:${color};transform:scale(${scale});">
              ${radar}
              <div class="pin-circle" style="background:${color};">${head}</div>
              <div class="pin-tail"></div>
              <div class="pin-ground"></div>
            </div>`,
      iconSize:[32,44], iconAnchor:[16,44], popupAnchor:[0,-42]
    });
  }
  function infraIcon(b){
    const meta = infraTypes[b.type] || infraTypes.bridge;
    const sz = infraSizes[b.size] || infraSizes.medium;
    const color = b.color || meta.color;
    const inner = b.icon_image ? `<img src="${pinThumb(b.icon_image)}" alt="" onerror="window.__infraImgFallback(this, '${meta.emoji}')">` : meta.emoji;
    return L.divIcon({
      className:'',
      html:`<div class="infra-pin" style="width:${sz.px}px;height:${sz.px}px;background:${color};font-size:${sz.font}px;">${inner}</div>`,
      iconSize:[sz.px, sz.px], iconAnchor:[sz.px/2, sz.px], popupAnchor:[0, -sz.px+2]
    });
  }

  const pinMarkerMap = new Map();
  // On touch devices there's no real "hover" — a tap can synthesize
  // mouseout/mouseleave as the finger lifts, which was closing the popup
  // out from under anyone trying to tap Enquire/WhatsApp/Share inside it.
  // On these devices the popup only closes via its own × button or by
  // tapping elsewhere on the map — never on a hover-out timer.
  const isTouchDevice = window.matchMedia('(hover: none)').matches;
  // Business WhatsApp number for the card's WhatsApp button — country code +
  // number, digits only, no + or spaces (e.g. '919876543210'). Replace this
  // before going live; until then the button links to a placeholder number.
  // Desktop only: shifts an open card so it stays fully visible (clear of
  // the top bar and screen edges) WITHOUT moving the map.
  function fitCardInView(popup){
    const el = popup && popup._container;
    if(!el) return;
    // _updatePosition only moves the card — it doesn't re-render content,
    // so buttons, listeners and the video player stay intact.
    popup.options.offset = [0, -2];
    popup._updatePosition();
    const mapRect = map.getContainer().getBoundingClientRect();
    const topbar = document.getElementById('topbar');
    const topLimit = Math.max(mapRect.top + 10, topbar ? topbar.getBoundingClientRect().bottom + 10 : 0);
    const bottomLimit = mapRect.bottom - 10, leftLimit = mapRect.left + 10, rightLimit = mapRect.right - 10;
    const r = el.getBoundingClientRect();
    let dx = 0, dy = 0;
    if(r.right > rightLimit) dx = rightLimit - r.right;
    if(r.left + dx < leftLimit) dx = leftLimit - r.left;
    if(r.bottom > bottomLimit) dy = bottomLimit - r.bottom;
    if(r.top + dy < topLimit) dy = topLimit - r.top;
    if(dx || dy){
      popup.options.offset = [dx, -2 + dy];
      popup._updatePosition();
    }
  }
  const WHATSAPP_NUMBER = '918881188181';
  // Call number for the sticky Call button — same format as above, no + or
  // spaces. Defaults to the WhatsApp number; change independently if your
  // sales line is different.
  const CALL_NUMBER = '918881188181';
  document.getElementById('sticky-whatsapp').href =
    `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent("Hi, I'm interested in a project on Mappingg.com. Could you share more details?")}`;
  document.getElementById('sticky-call').href = `tel:+${CALL_NUMBER}`;
  document.getElementById('sticky-whatsapp').addEventListener('click', ()=> trackEvent('lead', 'sticky_whatsapp_click', 'sticky-button'));
  document.getElementById('sticky-call').addEventListener('click', ()=> trackEvent('lead', 'sticky_call_click', 'sticky-button'));
  function whatsappUrl(pin){
    const msg = encodeURIComponent(`Hi, I'm interested in ${pin.title || 'this project'} on the Mappingg.com. Could you share more details?`);
    return `https://wa.me/${WHATSAPP_NUMBER}?text=${msg}`;
  }
  // Display-only field visibility — purely what the admin set for this
  // project in the editor's "Public Card Visibility" panel. No toggle
  // controls appear here; visitors just see the card as configured.
  function isFieldOn(pin, fieldId){
    const v = pin.field_visibility ? pin.field_visibility[fieldId] : undefined;
    return v !== false; // visible unless the admin explicitly turned it off
  }

  function renderPin(pin){
    if(pinMarkerMap.has(pin.id)) map.removeLayer(pinMarkerMap.get(pin.id));
    const marker = L.marker([pin.lat, pin.lng], {icon: pinIcon(pin)}).addTo(map);
    const color = statusColor[pin.status] || statusColor.available;
    // Card layout: the project's logo/marker image sits in its own banner
    // at the top of the popup. Further down, a "Project Brochure" section
    // shows the uploaded brochure image — swapping to the project's
    // YouTube video (muted autoplay) a few seconds after the popup opens,
    // if one is set. See the popupopen / popupclose handlers below.
    const logoHtml = pin.image ? `<div class="tc-logo-wrap"><img src="${pin.image}" alt=""></div>` : '';
    const videoId = extractYouTubeId(pin.youtube_video_url);
    // Project Brochure section: if a video is set, it plays immediately
    // (muted autoplay) when the popup opens — no image, no delay. The
    // brochure image only shows when there's no video for this project.
    // The box's shape defaults to widescreen (16:9) but the admin can set
    // their own width/height (a ratio or exact pixels) per project.
    const hasBrochure = !!(pin.brochure_image || videoId);
    const brochureImgHtml = (!videoId && pin.brochure_image) ? `<img class="tc-brochure-image" src="${pin.brochure_image}" alt="">` : '';
    const brochureVideoHtml = videoId ? `<div class="tc-video-wrap" data-video-id="${videoId}"></div>` : '';
    const brochureRatioStyle = (pin.brochure_width && pin.brochure_height)
      ? ` style="height:${Math.round((pin.brochure_height / pin.brochure_width) * 100)}px;"`
      : '';
    const brochureHtml = hasBrochure
      ? `<div class="tc-brochure-label">PROJECT VIDEO</div>
         <div class="tc-brochure-media"${brochureRatioStyle}>${brochureImgHtml}${brochureVideoHtml}</div>`
      : '';
    let pinVideoRevert = null;
    const shareBtn = `<button class="tc-share" data-share-pin="${pin.id}" type="button" aria-label="Share this project" title="Share this project">🔗<span class="tc-share-label"> Share</span></button>`;

    // The full "Project Card" field set. Project Name is the card header and
    // always shows; everything else only appears if the project has data
    // for it AND the admin hasn't hidden it in the editor.
    const configValue = [pin.configuration, pin.sqft].filter(Boolean).join(' · ');
    const possessionValue = pin.status === 'upcoming'
      ? (pin.launch_date ? 'Launching: ' + pin.launch_date : '')
      : (pin.possession_timeline ? 'Possession: ' + pin.possession_timeline : '');
    const fields = [
      pin.developer ? { id:'developer', label:'Developer', html:`<div class="tc-meta">${escapeHtml(pin.developer)}</div>` } : null,
      pin.location ? { id:'location', label:'Location', html:`<div class="tc-meta">${escapeHtml(pin.location)}</div>` } : null,
      { id:'status', label:'Status', html:`<span class="tc-status" style="background:${color};">${statusLabel[pin.status] || 'Available'}</span>` },
      pin.type ? { id:'type', label:'Property Type', html:`<span class="tc-type">${escapeHtml(pin.type)}</span>` } : null,
      pin.rera_number ? { id:'rera', label:'MahaRERA No.', html:`<div class="tc-meta tc-rera">${escapeHtml(pin.rera_number)}</div>` } : null,
      configValue ? { id:'configuration', label:'Configuration', html:`<div class="tc-meta">${escapeHtml(configValue)}</div>` } : null,
      pin.price ? { id:'price', label:'Starting Price', html:`<div class="tc-meta">${escapeHtml(pin.price)}</div>` } : null,
      possessionValue ? { id:'possession', label: pin.status === 'upcoming' ? 'Launch' : 'Possession', html:`<div class="tc-meta">${escapeHtml(possessionValue)}</div>` } : null,
      pin.key_usp ? { id:'key_usp', label:'Key USP', html:`<div class="tc-meta">${escapeHtml(pin.key_usp)}</div>` } : null
    ].filter(f => f && isFieldOn(pin, f.id));

    // Admin-added custom fields — each carries its own visible flag directly
    // (set per-field in the editor), so they don't go through isFieldOn.
    const customFields = Array.isArray(pin.custom_fields)
      ? pin.custom_fields.filter(cf => cf && cf.visible !== false && (cf.label || cf.value))
      : [];
    customFields.forEach(cf=>{
      fields.push({ id:'custom-' + cf.id, label: cf.label, html:`<div class="tc-meta">${cf.label ? `<strong>${escapeHtml(cf.label)}:</strong> ` : ''}${escapeHtml(cf.value || '')}</div>` });
    });

    // Card header is split 50/50: logo on the left, project name +
    // developer, location, status and type on the right. Everything else
    // (configuration, price, possession, USP, custom fields) runs full
    // width underneath.
    const headIds = ['developer','location','status','type'];
    const headFieldsHtml = fields.filter(f=> headIds.includes(f.id)).map(f=> `<div class="tc-field">${f.html}</div>`).join('');
    const fieldsHtml = fields.filter(f=> !headIds.includes(f.id)).map(f=> `<div class="tc-field">${f.html}</div>`).join('');

    // Enquire and WhatsApp are actions, not data — shown purely based on the
    // admin's Public Card Visibility setting for this project.
    const enquireBtn = isFieldOn(pin, 'enquire') ? `<button data-pin="${pin.id}" type="button" aria-label="Enquire now" title="Enquire now"><svg class="tc-enq-art" viewBox="0 0 60 60" aria-hidden="true"><circle cx="30" cy="30" r="29" fill="#2f3b93"/><text x="30" y="29" text-anchor="middle" font-family="Arial Narrow,Arial,Helvetica,sans-serif" font-weight="800" font-size="11" fill="#fff" textLength="44" lengthAdjust="spacingAndGlyphs">ENQUIRE</text><text x="30" y="42" text-anchor="middle" font-family="Arial Narrow,Arial,Helvetica,sans-serif" font-weight="800" font-size="12.5" fill="#fff" textLength="26" lengthAdjust="spacingAndGlyphs">NOW</text><g transform="translate(39 3) rotate(12)"><rect width="17" height="12" rx="1.5" fill="#e9b85c" stroke="#fff" stroke-width="1.2"/><path d="M1 1.2 L8.5 7 L16 1.2" fill="none" stroke="#8a5a14" stroke-width="1.1" stroke-linejoin="round"/></g></svg><span class="tc-enq-label">Enquire</span></button>` : '';
    const whatsappBtn = isFieldOn(pin, 'whatsapp') ? `<a class="tc-whatsapp" href="${whatsappUrl(pin)}" target="_blank" rel="noopener" aria-label="WhatsApp" title="WhatsApp"><svg viewBox="0 0 32 32" fill="currentColor" aria-hidden="true"><path d="M16.02 3C9.4 3 4 8.38 4 15c0 2.29.64 4.44 1.75 6.28L4 29l7.94-1.7A11.94 11.94 0 0 0 16.02 27C22.65 27 28 21.63 28 15S22.65 3 16.02 3zm0 21.7c-1.95 0-3.77-.55-5.32-1.5l-.38-.23-4.71 1.01 1-4.6-.25-.4A9.63 9.63 0 0 1 6.3 15c0-5.36 4.36-9.7 9.72-9.7 5.36 0 9.72 4.34 9.72 9.7 0 5.36-4.36 9.7-9.72 9.7zm5.34-7.27c-.29-.15-1.73-.86-2-.95-.27-.1-.46-.15-.66.15-.2.29-.76.95-.93 1.15-.17.19-.34.22-.63.07-.29-.15-1.2-.44-2.29-1.41-.85-.75-1.42-1.68-1.59-1.97-.17-.29-.02-.45.13-.6.13-.13.29-.34.44-.51.15-.17.19-.29.29-.49.1-.19.05-.36-.02-.51-.07-.15-.66-1.6-.9-2.19-.24-.57-.48-.5-.66-.5-.17-.01-.36-.01-.56-.01-.19 0-.51.07-.78.36-.27.29-1.02 1-1.02 2.43 0 1.43 1.05 2.82 1.19 3.01.15.19 2.06 3.15 5 4.42.7.3 1.24.48 1.67.62.7.22 1.34.19 1.84.12.56-.08 1.73-.71 1.98-1.39.24-.68.24-1.27.17-1.39-.07-.12-.26-.19-.55-.34z"/></svg><span class="tc-wa-label">WhatsApp</span></a>` : '';

    const titleHtml = isFieldOn(pin, 'name') ? `<p class="tc-title">${escapeHtml(pin.title || 'Untitled project')}</p>` : '';
    const html = `<div class="teaser-card">
      <div class="tc-top${logoHtml ? '' : ' no-logo'}">
        ${logoHtml}
        <div class="tc-head">${titleHtml}${headFieldsHtml}</div>
      </div>
      <div class="tc-body">
        ${fieldsHtml ? `<div class="tc-details">${fieldsHtml}</div>` : ''}
        ${brochureHtml}
        <div class="tc-actions">
          ${enquireBtn}
          ${whatsappBtn}
          ${shareBtn}
        </div>
      </div></div>`;
    marker.bindPopup(html, {
      closeButton:false, className:'teaser-popup', offset:[0,-2], autoClose:false, closeOnClick:false,
      // Keeps the card clear of the fixed search bar at the top of the
      // screen and off the very edges on mobile, instead of opening flush
      // against it (which is what made it look like one long merged card).
      // Desktop: the map never pans when a card opens — the card is nudged
      // to stay on screen instead (see fitCardInView). Touch keeps autoPan.
      autoPan: isTouchDevice,
      autoPanPaddingTopLeft:[12, 90], autoPanPaddingBottomRight:[12, 20]
    });
    // Regular pins: the card opens on click/tap and stays until × or a map click.
    // Blinking (highlighted) pins on desktop: the card also opens on hover and
    // closes again on hover-out — unless it was clicked open, which pins it.
    const opensOnHover = !!pin.highlighted && !isTouchDevice;
    let openedByHover = false;
    let closeTimer = null;
    function scheduleClose(){ if(!openedByHover) return; closeTimer = setTimeout(()=> marker.closePopup(), 400); }
    function cancelClose(){ if(closeTimer){ clearTimeout(closeTimer); closeTimer = null; } }
    marker.on('mouseover', ()=>{
      if(!opensOnHover) return;
      cancelClose();
      if(!marker.isPopupOpen()){ openedByHover = true; marker.openPopup(); }
    });
    marker.on('mouseout', scheduleClose);
    marker.on('click', (ev)=>{
      L.DomEvent.stopPropagation(ev);
      cancelClose();
      openedByHover = false;
      marker.openPopup();
    });
    marker.on('popupclose', ()=>{ openedByHover = false; cancelClose(); });
    marker.on('popupopen', (e)=>{
      if(!isTouchDevice){
        fitCardInView(e.popup);
        const logoImg = e.popup._contentNode.querySelector('.tc-logo-wrap img');
        if(logoImg && !logoImg.complete) logoImg.addEventListener('load', ()=> fitCardInView(e.popup), {once:true});
      }
      // Our own close (×) button, fixed to the popup frame so it never
      // scrolls away with a long card, and large enough to tap on mobile.
      // (Leaflet's built-in one was unreliable to tap on phones.)
      const frame = e.popup._container;
      if(frame && !frame.querySelector('.tc-close')){
        const closeBtn = L.DomUtil.create('button', 'tc-close', frame);
        closeBtn.type = 'button';
        closeBtn.setAttribute('aria-label', 'Close');
        closeBtn.innerHTML = '&times;';
        L.DomEvent.disableClickPropagation(closeBtn);
        L.DomEvent.on(closeBtn, 'click', (ev)=>{ L.DomEvent.stop(ev); marker.closePopup(); });
      }
      const btn = e.popup._contentNode.querySelector('button[data-pin]');
      if(btn) btn.addEventListener('click', ()=>{ trackEvent('lead', 'enquire_click', pin.title || ('#' + pin.number)); requestDetails(pin); });
      const waBtnEl = e.popup._contentNode.querySelector('a.tc-whatsapp');
      if(waBtnEl) waBtnEl.addEventListener('click', ()=> trackEvent('lead', 'whatsapp_click', pin.title || ('#' + pin.number)));
      const shareBtnEl = e.popup._contentNode.querySelector('button[data-share-pin]');
      if(shareBtnEl) shareBtnEl.addEventListener('click', (evt)=>{ evt.stopPropagation(); sharePin(pin); });
      const popupEl = e.popup._container;
      if(popupEl){
        popupEl.addEventListener('mouseenter', cancelClose);
        popupEl.addEventListener('mouseleave', scheduleClose);
        // Stop map clicks inside the popup from closing it or firing other pins
        L.DomEvent.on(popupEl, 'click', L.DomEvent.stopPropagation);
      }
      // If a video is set, play it immediately using the official YouTube
      // IFrame Player API (not a plain iframe) — this is what reliably
      // fires onError when a video owner has disabled embedding, which a
      // raw <iframe src="...embed/..."> does NOT do on its own (that's
      // why the previous approach still showed YouTube's own broken
      // "Error 153" screen instead of our clean fallback). Two safety
      // nets so something always actually displays: (1) the video's own
      // YouTube thumbnail sits behind the player as a poster, visible the
      // instant the card opens; (2) onError swaps this area to a "Watch
      // Video" button instead of YouTube's own error screen.
      const videoWrap = e.popup._contentNode.querySelector('.tc-video-wrap');
      if(videoWrap){
        const vid = videoWrap.dataset.videoId;
        videoWrap.classList.add('playing');
        videoWrap.style.background = `#000 url('https://img.youtube.com/vi/${vid}/hqdefault.jpg') center/cover no-repeat`;

        const playerDivId = 'yt-player-' + pin.id + '-' + Date.now();
        // Build the iframe ourselves so it always sends a referrer and the
        // autoplay permission — this is what lets it start playing
        // straight away (muted) on mobile and desktop.
        const playerDiv = document.createElement('iframe');
        playerDiv.id = playerDivId;
        playerDiv.src = 'https://www.youtube.com/embed/' + vid +
          '?autoplay=1&mute=1&playsinline=1&controls=1&rel=0&modestbranding=1&loop=1&playlist=' + vid +
          '&enablejsapi=1&origin=' + encodeURIComponent(location.origin);
        playerDiv.setAttribute('allow', 'autoplay; encrypted-media; picture-in-picture');
        playerDiv.setAttribute('allowfullscreen', '');
        playerDiv.setAttribute('referrerpolicy', 'strict-origin-when-cross-origin');
        playerDiv.setAttribute('title', 'Project video');
        videoWrap.appendChild(playerDiv);

        let ytPlayer = null;
        let destroyed = false;
        const showFallback = ()=>{
          if(destroyed) return;
          videoWrap.innerHTML = `<a href="https://www.youtube.com/watch?v=${vid}" target="_blank" rel="noopener" class="tc-video-fallback">▶ Watch Video</a>`;
        };
        whenYouTubeApiReady(()=>{
          if(destroyed) return;
          try{
            ytPlayer = new YT.Player(playerDivId, {
              events:{
                onReady:(ev)=>{ try{ ev.target.mute(); ev.target.playVideo(); }catch(err){} },
                // 101/150 = embedding disabled by the video owner; 100 = removed
                // or private; 2 = invalid id; 5 = HTML5 player error.
                onError: showFallback
              }
            });
          }catch(err){ showFallback(); }
        });

        pinVideoRevert = function(){
          destroyed = true;
          try{ if(ytPlayer && ytPlayer.destroy) ytPlayer.destroy(); }catch(err){}
          videoWrap.classList.remove('playing');
          videoWrap.innerHTML = '';
          videoWrap.style.background = '';
          videoWrap.style.cursor = '';
        };
      }
    });
    marker.on('popupopen', (e)=>{
      const wrap = e.popup._wrapper;
      const acts = e.popup._contentNode.querySelector('.tc-actions');
      if(!wrap || !acts) return;
      wrap.querySelectorAll(':scope > .tc-actions-float').forEach(n=> n.remove());
      // The original button row stays hidden inside the card (so it can
      // never show up as a second set of buttons). The floating column is
      // a copy whose taps are passed on to the originals.
      const float = acts.cloneNode(true);
      float.classList.add('tc-actions-float');
      wrap.appendChild(float);
      L.DomEvent.disableClickPropagation(float);
      const forward = (sel)=>{
        const b = float.querySelector(sel);
        if(!b) return;
        b.addEventListener('click', (ev)=>{
          ev.preventDefault(); ev.stopPropagation();
          const orig = e.popup._contentNode.querySelector(sel);
          if(orig) orig.click();
        });
      };
      forward('button[data-pin]');
      forward('button[data-share-pin]');
      const waFloat = float.querySelector('a.tc-whatsapp');
      if(waFloat) waFloat.addEventListener('click', ()=> trackEvent('lead', 'whatsapp_click', pin.title || ('#' + pin.number)));
    });
    marker.on('popupclose', ()=>{
      // Stop playback when the popup closes so it starts fresh next time.
      if(pinVideoRevert){ pinVideoRevert(); pinVideoRevert = null; }
    });
    pinMarkerMap.set(pin.id, marker);
  }

  pins.forEach(renderPin);

  // ---------- Live sync from the editor ----------
  // Any change an admin makes in the editor — including flipping a Public
  // Card Visibility switch — updates this row in Supabase, and this
  // subscription pushes that change to every visitor's map instantly,
  // with no page refresh needed.
  let reloadTimer = null;
  function scheduleReload(delay){
    clearTimeout(reloadTimer);
    reloadTimer = setTimeout(reloadPins, delay == null ? 800 : delay);
  }
  async function reloadPins(){
    const data = await fetchPinsLight();
    // Load failed: keep every pin already on the map and try again soon.
    if(!data){ scheduleReload(5000); return; }
    applyCachedImages(data);
    pins = data;
    pinMarkerMap.forEach(m=> map.removeLayer(m));
    pinMarkerMap.clear();
    pins.forEach(renderPin);
    loadPinImages(pins);
  }
  // Several edits in a row (the editor saves field by field) now trigger
  // one refresh instead of a burst of heavy reloads.
  sb.channel('public-pins-changes')
    .on('postgres_changes', { event: '*', schema: 'public', table: 'pins' }, ()=> scheduleReload())
    .subscribe();
  // If the very first load failed, keep retrying until the pins appear.
  if(!pins.length) scheduleReload(3000);
  loadPinImages(pins);

  // Default view on load: every visitor's location is fetched automatically
  // and the map centres on whichever of our projects are actually near
  // them — no button tap needed. Falls back to the full-radius view if
  // location is denied/unavailable, so TV/kiosk screens and anyone who says
  // no to the permission prompt still land on a normal, usable map. A
  // shared pin link (?pin=<id>) is the one exception — that still zooms
  // straight to the specific project being shared, skipping geolocation.
  (function focusOnLoad(){
    const urlPinId = new URLSearchParams(window.location.search).get('pin');
    const sharedPin = urlPinId ? pins.find(p => p.id === urlPinId) : null;
    if(sharedPin){
      const marker = pinMarkerMap.get(sharedPin.id);
      if(marker){
        map.setView([sharedPin.lat, sharedPin.lng], 17, { animate:true });
        setTimeout(()=> marker.openPopup(), 650);
      }
      return;
    }
    locateAndShowNearby({ silent:true });
  })();

  bridges.forEach(b=>{
    const marker = L.marker([b.lat, b.lng], {icon: infraIcon(b)}).addTo(map);
    marker.bindPopup(infraHoverContent(b), {closeButton:false, className:'infra-hover-popup', offset:[0,-4]});
    marker.on('mouseover', ()=> marker.openPopup());
    marker.on('mouseout', ()=> marker.closePopup());
  });

  const roadWeights = {small:3, medium:5, large:8};
  function isBridgeLike(type){ return type === 'bridge' || type === 'highway_bridge' || type === 'flyover'; }
  roads.forEach(r=>{
    if(!r.points || r.points.length < 2) return;
    const meta = infraTypes[r.type] || infraTypes.proposed_road;
    const color = r.color || meta.color;
    const weight = r.weight || 5;
    const isMetro = r.type === 'metro_line';
    if(isBridgeLike(r.type)){
      L.polyline(r.points, {
        color:'#ffffff', weight: weight + 6, opacity:0.9, lineJoin:'round', lineCap:'round', interactive:false
      }).addTo(map);
    }
    const line = L.polyline(r.points, {
      color, weight: isMetro ? Math.min(weight, 3) : weight, opacity:0.95,
      dashArray: (r.type === 'proposed_road') ? '10,8' : (isMetro ? '7,5' : null),
      lineJoin:'round', lineCap:'round'
    }).addTo(map);
    if(r.title || r.notes) line.bindPopup(roadHoverContent(r), {closeButton:false, className:'road-hover-popup'});
  });

  const overlayBg = document.getElementById('overlay-bg');
  const leadBox = document.getElementById('lead-box');
  const detailPanel = document.getElementById('detail-panel');
  const leadRole = document.getElementById('lead-role');
  const leadName = document.getElementById('lead-name');
  const leadWhatsapp = document.getElementById('lead-whatsapp');
  const leadWhatsappCode = document.getElementById('lead-whatsapp-code');
  leadWhatsapp.addEventListener('input', ()=>{
    leadWhatsapp.value = leadWhatsapp.value.replace(/\D/g, '').slice(0, 10);
  });
  const leadEmail = document.getElementById('lead-email');
  const leadConsent = document.getElementById('lead-consent');
  const leadError = document.getElementById('lead-error');
  const leadSubmit = document.getElementById('lead-submit');
  const leadCancel = document.getElementById('lead-cancel');
  const leadTitle = document.getElementById('lead-title');

  let pendingPin = null;

  function unlockKey(pinId){ return 'lead_unlocked_' + pinId; }

  function requestDetails(pin){
    map.closePopup();
    if(localStorage.getItem(unlockKey(pin.id))){
      showDetails(pin);
      return;
    }
    pendingPin = pin;
    leadTitle.textContent = 'See full details — ' + (pin.title || 'this project');
    leadError.textContent = '';
    leadName.value = ''; leadWhatsapp.value = ''; leadEmail.value = '';
    leadWhatsappCode.value = '+91';
    leadRole.value = 'buyer';
    leadConsent.checked = true;
    leadBox.style.display = 'block';
    detailPanel.classList.remove('open');
    overlayBg.classList.add('open');
  }

  leadCancel.addEventListener('click', ()=>{
    overlayBg.classList.remove('open');
    leadBox.style.display = 'none';
    pendingPin = null;
  });
  overlayBg.addEventListener('click', (e)=>{ if(e.target === overlayBg){ overlayBg.classList.remove('open'); leadBox.style.display='none'; pendingPin=null; } });

  let leadSubmitInProgress = false;
  leadSubmit.addEventListener('click', async ()=>{
    // Guards against a submission firing twice from a single tap — some
    // touchscreens/browsers can generate two click events for one physical
    // tap faster than the disabled-attribute check below can catch it.
    if(leadSubmitInProgress) return;
    leadSubmitInProgress = true;
    try{
    const name = leadName.value.trim();
    const whatsappDigits = leadWhatsapp.value.trim();
    const email = leadEmail.value.trim();
    const role = leadRole.value;
    if(!name || !whatsappDigits || !email){
      leadError.textContent = 'Please fill in all fields.';
      return;
    }
    if(!/^\d{10}$/.test(whatsappDigits)){
      leadError.textContent = 'WhatsApp number must be exactly 10 digits.';
      return;
    }
    const whatsapp = leadWhatsappCode.value + ' ' + whatsappDigits;
    if(!/^\S+@\S+\.\S+$/.test(email)){
      leadError.textContent = 'Please enter a valid email.';
      return;
    }
    if(!leadConsent.checked){
      leadError.textContent = 'Please provide consent to continue.';
      return;
    }
    leadSubmit.disabled = true;
    leadSubmit.textContent = 'Submitting…';
    const { error } = await sb.from('leads').insert({
      pin_id: pendingPin.id, role, name, whatsapp, email, consent: leadConsent.checked
    });
    leadSubmit.disabled = false;
    leadSubmit.textContent = 'View Details';
    if(error){
      leadError.textContent = 'Something went wrong — please try again.';
      return;
    }
    localStorage.setItem(unlockKey(pendingPin.id), '1');
    trackEvent('lead', 'lead_submitted', pendingPin.title || ('#' + pendingPin.number));

    // Also sends this lead to your Google Sheet, via the Apps Script Web
    // App you deploy separately (see google-sheets-lead-webhook.gs). This
    // never blocks or fails the actual submission above — if the Sheet is
    // slow, offline, or not set up yet, the lead is still saved to Supabase
    // and the visitor sees no difference either way.
    const SHEETS_WEBHOOK_URL = 'https://script.google.com/macros/s/AKfycbwrD-sBwB_3AiX9X-aLUR-3BPNdsVohTC0ZbHp_nNUsV4HrTLZ9hmBemH9sKs_sFZDg/exec';
    if(SHEETS_WEBHOOK_URL){
      fetch(SHEETS_WEBHOOK_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({
          project: pendingPin.title || ('#' + pendingPin.number),
          role, name, whatsapp, email, consent: leadConsent.checked
        })
      }).catch(()=>{ /* fails silently — Supabase above is the source of truth */ });
    }

    leadBox.style.display = 'none';
    showDetails(pendingPin);
    } finally {
      leadSubmitInProgress = false;
    }
  });

  function showDetails(pin){
    const color = statusColor[pin.status] || statusColor.available;
    const img = document.getElementById('detail-img');
    if(pin.image){ img.src = pin.image; img.style.display = 'block'; }
    else { img.style.display = 'none'; }

    let rows = '';
    if(pin.status === 'sold'){
      rows = `<div class="detail-row"><label>Status</label><div class="value">This project has been sold out.</div></div>`;
    } else {
      if(pin.price) rows += `<div class="detail-row"><label>Price</label><div class="value price">${escapeHtml(pin.price)}</div></div>`;
      if(pin.status === 'construction' || pin.status === 'upcoming'){
        if(pin.configuration) rows += `<div class="detail-row"><label>Configuration</label><div class="value">${escapeHtml(pin.configuration)}</div></div>`;
        if(pin.sqft) rows += `<div class="detail-row"><label>Sq Ft</label><div class="value">${escapeHtml(pin.sqft)}</div></div>`;
      }
      if(pin.status === 'construction' && pin.possession_timeline)
        rows += `<div class="detail-row"><label>Possession Timeline</label><div class="value">${escapeHtml(pin.possession_timeline)}</div></div>`;
      if(pin.status === 'upcoming' && pin.launch_date)
        rows += `<div class="detail-row"><label>Approximate Launch Date</label><div class="value">${escapeHtml(pin.launch_date)}</div></div>`;
      if(pin.status === 'available' && pin.whats_available)
        rows += `<div class="detail-row"><label>What's Available</label><div class="value">${escapeHtml(pin.whats_available)}</div></div>`;
    }
    if(pin.description) rows += `<div class="detail-row"><label>Description</label><div class="value">${escapeHtml(pin.description)}</div></div>`;

    const detailShareBtn = `<button class="detail-share" type="button" id="detail-share-btn">🔗 Share this project</button>`;
    document.getElementById('detail-body').innerHTML = `
      <h2>${escapeHtml(pin.title || 'Untitled project')}</h2>
      <span class="status-badge" style="background:${color};">${statusLabel[pin.status] || 'Available'}</span>
      ${pin.developer ? `<div class="detail-row"><label>Developer</label><div class="value">${escapeHtml(pin.developer)}</div></div>` : ''}
      ${pin.location ? `<div class="detail-row"><label>Location</label><div class="value">${escapeHtml(pin.location)}</div></div>` : ''}
      ${pin.type ? `<div class="detail-row"><label>Type</label><div class="value">${escapeHtml(pin.type)}</div></div>` : ''}
      ${pin.rera_number && isFieldOn(pin, 'rera') ? `<div class="detail-row"><label>MahaRERA No.</label><div class="value">${escapeHtml(pin.rera_number)}</div></div>` : ''}
      ${rows}
      ${pin.key_usp ? `<div class="detail-row"><label>Key USP</label><div class="value">${escapeHtml(pin.key_usp)}</div></div>` : ''}
      ${detailShareBtn}
    `;
    const shareEl = document.getElementById('detail-share-btn');
    if(shareEl) shareEl.addEventListener('click', ()=> sharePin(pin));
    overlayBg.classList.add('open');
    detailPanel.classList.add('open');
  }

