    legalOverlay.classList.add('open');
  }
  function closeLegalModal(){ legalOverlay.classList.remove('open'); }
  // Exposed globally so the attribution control's inline onclick (built as a plain
  // HTML string outside this closure) can call it.
  window.openLegalModal = openLegalModal;

  document.getElementById('legal-close').addEventListener('click', closeLegalModal);
  legalOverlay.addEventListener('click', (e)=>{ if(e.target === legalOverlay) closeLegalModal(); });
  document.addEventListener('keydown', (e)=>{ if(e.key === 'Escape') closeLegalModal(); });

  // ---------- Area / locality search ----------
  // Typing a known Pune-area name focuses the map on that locality. Mundhwa
  // is handled as a fixed, single reference point (same centre every time)
  // with the Associatte pin auto-opened and highlighted — since that's your
  // home project. Every other locality (Kharadi, Solapur Highway,
  // NIBM/Lullanagar, Viman Nagar, and anything else added later in the admin
  // tool) is data-driven from the area_boundaries table: once you draw that
  // locality's boundary there, search zooms to the exact drawn shape (and to
  // your actual project pins inside it, once you have some); until then it
  // falls back to a wider reference view around that locality's centre.
  const MUNDHWA_CENTER = { lat: 18.5215, lng: 73.9140, zoom: 15.5 };
  const MUNDHWA_MATCH = ['mundhwa'];

  const knownAreas = areaBoundaries.map(a => ({
    id: a.id,
    label: a.label,
    match: a.match || [],
    drawnBoundary: (a.boundary && a.boundary.length >= 3) ? a.boundary : null,
    fallbackLat: a.fallback_lat,
    fallbackLng: a.fallback_lng,
    fallbackZoom: a.fallback_zoom || 14
  }));

  const areaToastEl = document.getElementById('area-toast');
  let areaToastTimer = null;
  function showAreaToast(text){
    areaToastEl.textContent = '📍 ' + text;
    areaToastEl.classList.add('show');
    clearTimeout(areaToastTimer);
    areaToastTimer = setTimeout(()=> areaToastEl.classList.remove('show'), 2600);
  }

  function textMatches(q, aliasList){
    return aliasList.some(alias => alias.includes(q) || q.includes(alias));
  }

  // Generic point-in-polygon (ray-casting) test — used both for your main
  // Mundhwa boundary and for any locality boundary drawn in the admin tool.
  function isInsidePolygon(lat, lng, polygon){
    if(!polygon || polygon.length < 3) return false;
    const x = lat, y = lng;
    let inside = false;
    for(let i = 0, j = polygon.length - 1; i < polygon.length; j = i++){
      const xi = polygon[i][0], yi = polygon[i][1];
      const xj = polygon[j][0], yj = polygon[j][1];
      const intersects = ((yi > y) !== (yj > y)) &&
        (x < (xj - xi) * (y - yi) / (yj - yi) + xi);
      if(intersects) inside = !inside;
    }
    return inside;
  }
  function isInsideMundhwaBoundary(lat, lng){ return isInsidePolygon(lat, lng, boundary); }

  // Pins that actually belong to a given (non-Mundhwa) area: inside its drawn
  // boundary if one exists, otherwise within a rough box of its fallback
  // centre — but never anything that's really inside the main Mundhwa
  // boundary, so that cluster can't leak into another locality's results.
  const FALLBACK_RADIUS = 0.03;
  function pinsInArea(area){
    if(area.drawnBoundary){
      return pins.filter(p => isInsidePolygon(p.lat, p.lng, area.drawnBoundary));
    }
    if(area.fallbackLat == null || area.fallbackLng == null) return [];
    return pins.filter(p =>
      Math.abs(p.lat - area.fallbackLat) <= FALLBACK_RADIUS &&
      Math.abs(p.lng - area.fallbackLng) <= FALLBACK_RADIUS &&
      !isInsideMundhwaBoundary(p.lat, p.lng)
    );
  }

  // Briefly pulses a marker (like the "highlighted" glow) without touching
  // its stored data — used when search brings a specific project into focus.
  function pulseMarker(marker){
    const el = marker.getElement && marker.getElement();
    const wrap = el && el.querySelector('.pin-wrap');
    if(!wrap || wrap.querySelector('.pin-radar')) return;
    const radar = document.createElement('div');
    radar.className = 'pin-radar';
    wrap.insertBefore(radar, wrap.firstChild);
    setTimeout(()=> radar.remove(), 4200);
  }

  function focusMundhwa(){
    map.flyTo([MUNDHWA_CENTER.lat, MUNDHWA_CENTER.lng], MUNDHWA_CENTER.zoom, { animate:true, duration:1.1 });
    pins.forEach(pin=>{
      const marker = pinMarkerMap.get(pin.id);
      if(marker && !map.hasLayer(marker)) marker.addTo(map);
    });
    const companyPin = pins.find(p => p.number === 1) ||
      pins.find(p => (p.title || '').toLowerCase().includes('associatte'));
    if(companyPin){
      const marker = pinMarkerMap.get(companyPin.id);
      if(marker){
        setTimeout(()=>{
          if(!window.matchMedia('(max-width:640px), (hover: none)').matches) marker.openPopup();
          pulseMarker(marker);
        }, 900);
      }
    }
    showAreaToast('Mundhwa, Pune');
  }

  function focusArea(area){
    pins.forEach(pin=>{
      const marker = pinMarkerMap.get(pin.id);
      if(marker && !map.hasLayer(marker)) marker.addTo(map);
    });
    const nearbyPins = pinsInArea(area);
    if(nearbyPins.length){
      // Projects exist here — fit tightly around them with a bit of extra
      // zoom so they're clearly the focus, not lost in a wide shot.
      const bounds = L.latLngBounds(nearbyPins.map(p => [p.lat, p.lng]));
      map.flyToBounds(bounds, { padding:[90,90], maxZoom:17, animate:true, duration:1.1 });
      showAreaToast(`${area.label} — ${nearbyPins.length} project${nearbyPins.length > 1 ? 's' : ''}`);
    } else if(area.drawnBoundary){
      // No projects yet, but the locality's boundary has been drawn —
      // zoom straight to that exact shape.
      map.flyToBounds(L.latLngBounds(area.drawnBoundary), { padding:[50,50], animate:true, duration:1.1 });
      showAreaToast(`${area.label} — no projects added yet`);
    } else if(area.fallbackLat != null && area.fallbackLng != null){
      // No boundary drawn yet either — fall back to a general reference view.
      map.flyTo([area.fallbackLat, area.fallbackLng], area.fallbackZoom, { animate:true, duration:1.1 });
      showAreaToast(`${area.label} — no projects added yet`);
    }
  }

  // ---------- Search suggestions, built from your own listing data ----------
  // Project names, locations, and configuration types (2 BHK, 3 BHK, etc.)
  // pulled straight from your pins — never a random real-world place. This
  // is what should power public search; the Google location search is for
  // the admin editor only, where navigating anywhere makes sense.
  function buildSearchSuggestions(){
    const seen = new Map(); // label (lowercase) -> {label, type, pin?, area?}
    pins.forEach(pin=>{
      if(pin.title){
        seen.set(pin.title.toLowerCase(), { label: pin.title, type: 'Project', pin });
      }
      if(pin.location){
        const key = pin.location.toLowerCase();
        if(!seen.has(key)) seen.set(key, { label: pin.location, type: 'Location' });
      }
      if(pin.configuration){
        pin.configuration.split(/[,/]/).map(s=>s.trim()).filter(Boolean).forEach(cfg=>{
          const key = cfg.toLowerCase();
          if(!seen.has(key)) seen.set(key, { label: cfg, type: 'Configuration' });
        });
      }
    });
    knownAreas.forEach(area=>{
      const key = area.label.toLowerCase();
      if(!seen.has(key)) seen.set(key, { label: area.label, type: 'Area', area });
    });
    if(!seen.has('mundhwa')) seen.set('mundhwa', { label: 'Mundhwa', type: 'Area', isMundhwa: true });
    return Array.from(seen.values());
  }

  const searchSuggestionsEl = document.getElementById('search-suggestions');
  let searchSuggestionsData = [];
  let activeSuggestionIndex = -1;

  function renderSuggestions(list){
    activeSuggestionIndex = -1;
    if(!list.length){ searchSuggestionsEl.classList.remove('open'); searchSuggestionsEl.innerHTML=''; return; }
    searchSuggestionsEl.innerHTML = list.map((s,i)=>
      `<div class="suggestion-item" data-i="${i}"><span>${s.label}</span><span class="sg-type">${s.type}</span></div>`
    ).join('');
    searchSuggestionsEl.classList.add('open');
    searchSuggestionsEl.querySelectorAll('.suggestion-item').forEach(el=>{
      el.addEventListener('click', ()=> selectSuggestion(list[Number(el.dataset.i)]));
    });
  }

  function selectSuggestion(s){
    const input = document.getElementById('search-input');
    input.value = s.label;
    searchSuggestionsEl.classList.remove('open');
    if(s.isMundhwa){ focusMundhwa(); return; }
    if(s.type === 'Area' && s.area){ focusArea(s.area); return; }
    applySearchFilter(s.label);
    if(s.type === 'Project' && s.pin){
      const marker = pinMarkerMap.get(s.pin.id);
      if(marker){
        map.flyTo([s.pin.lat, s.pin.lng], 16, { duration: 1 });
        setTimeout(()=>{ marker.openPopup(); pulseMarker(marker); }, 700);
      }
    }
  }

  function applySearchFilter(rawQ){
    const q = rawQ.trim().toLowerCase();

    if(q.length >= 3){
      if(textMatches(q, MUNDHWA_MATCH)){ focusMundhwa(); return; }
      const areaMatch = knownAreas.find(area => textMatches(q, area.match));
      if(areaMatch){ focusArea(areaMatch); return; }
    }

    const matches = [];
    pins.forEach(pin=>{
      const marker = pinMarkerMap.get(pin.id);
      const haystack = [pin.title, pin.location, pin.configuration, pin.sqft, pin.whats_available]
        .filter(Boolean).join(' ').toLowerCase();
      const isMatch = !q || haystack.includes(q);
      if(isMatch){
        if(!map.hasLayer(marker)) marker.addTo(map);
        matches.push(pin);
      } else {
        if(map.hasLayer(marker)) map.removeLayer(marker);
      }
    });
    if(q && matches.length){
      const bounds = L.latLngBounds(matches.map(p=>[p.lat, p.lng]));
      map.fitBounds(bounds, {padding:[80,80], maxZoom:16});
    }
  }

  searchSuggestionsData = buildSearchSuggestions();

  document.getElementById('search-input').addEventListener('input', (e)=>{
    const q = e.target.value.trim().toLowerCase();
    applySearchFilter(e.target.value);
    if(!q){ renderSuggestions([]); return; }
    const matches = searchSuggestionsData
      .filter(s => s.label.toLowerCase().includes(q))
      .slice(0, 8);
    renderSuggestions(matches);
  });

  document.getElementById('search-input').addEventListener('keydown', (e)=>{
    const items = searchSuggestionsEl.querySelectorAll('.suggestion-item');
    if(!items.length) return;
    if(e.key === 'ArrowDown'){
      e.preventDefault();
      activeSuggestionIndex = Math.min(activeSuggestionIndex + 1, items.length - 1);
    } else if(e.key === 'ArrowUp'){
      e.preventDefault();
      activeSuggestionIndex = Math.max(activeSuggestionIndex - 1, 0);
    } else if(e.key === 'Enter' && activeSuggestionIndex >= 0){
      e.preventDefault();
      items[activeSuggestionIndex].click();
      return;
    } else if(e.key === 'Escape'){
      renderSuggestions([]);
      return;
    } else {
      return;
    }
    items.forEach((el,i)=> el.classList.toggle('active', i === activeSuggestionIndex));
  });

  document.addEventListener('click', (e)=>{
    if(!e.target.closest('#toolbar')) renderSuggestions([]);
  });

  // ---------- View-source deterrent: TEMPORARILY DISABLED ----------
  // Right-click / DevTools blocking is off while debugging the search
  // feature. Say the word and I'll switch it back on.

})();
